const body = $input.first()?.json?.body || $input.first()?.json || {};
const text = String(body.text || body.prompt || body.objective || '').trim();
const taskId = String(body.task_id || `hq-${new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14)}-draft`);
const workspace = String(body.workspace_path || '/home/ubuntu/workspace/true-autonomous-controller');
const queueItem = {
  task_id: taskId,
  created_at: new Date().toISOString(),
  requested_by: String(body.requested_by || 'telegram_user'),
  source_channel: String(body.source_channel || 'n8n_webhook'),
  priority: String(body.priority || 'normal'),
  objective: text || 'Draft HQ dispatch task',
  allowed_scope: ['local_files', 'offline_tests', 'docs', 'templates', 'scaffold', 'dry_run', 'no_live_network', 'no_secrets', 'no_production_mutation'],
  deferred_gates: [
    { name: 'live_ssh_dispatch_to_ec2', reason: 'This workflow is inactive draft only.', required_approval: 'Approve live SSH dispatch separately.' }
  ],
  target_runner: String(body.target_runner || 'codex'),
  tmux_session: String(body.tmux_session || 'tac-hq-runner'),
  workspace_path: workspace,
  validation_commands: ['python -m unittest discover -s tests', 'python scripts/run_offline_validations.py'],
  expected_artifacts: ['reports/hq_runtime_orchestration_final_report_2026-05-18.md'],
  status: 'QUEUED',
  retry_count: 0,
  max_retries: 3,
  continuation_ledger_path: 'reports/hq_continuation_ledger_2026-05-18.json',
  final_report_path: 'reports/hq_runtime_orchestration_final_report_2026-05-18.md'
};
return [{ json: { draft_only: true, active_dispatch: false, task_id: taskId, queue_item: queueItem } }];

const item = $json.queue_item;
const allowed = item.workspace_path.startsWith('/home/ubuntu/workspace/') && item.allowed_scope.includes('no_secrets') && item.allowed_scope.includes('no_production_mutation');
return [{ json: { ...$json, validation_status: allowed ? 'PASS' : 'DEFERRED_GATE', validation_reason: allowed ? 'safe draft scope' : 'workspace or scope rejected' } }];

const q = JSON.stringify($json.queue_item).replace(/'/g, `'"'"'`);
const command = [
  'cd /home/ubuntu/workspace/true-autonomous-controller',
  `printf '%s\\n' '${q}' >> runtime/queue/pending.jsonl`,
  `tmux has-session -t ${$json.queue_item.tmux_session} || tmux new-session -d -s ${$json.queue_item.tmux_session} 'bash scripts/hq_tmux_runner_template.sh'`
].join(' && ');
return [{ json: { ...$json, ssh_command_template: command, ssh_execution: 'DEFERRED_GATE_DRAFT_ONLY' } }];

const status = $json.validation_status === 'PASS' ? 'QUEUED_DRAFT' : 'DEFERRED_GATE';
const summary = [
  '[Kindred AI Controller]',
  `status: ${status}`,
  `task_id: ${$json.task_id}`,
  'draft_only: true',
  'live_ssh_executed: false',
  'next: import inactive only, then approve live SSH dispatch separately if needed'
].join('\n');
return [{ json: { ...$json, status, telegram_summary_template: summary } }];
